/** Live acceptance against a running dsh-voice-unified host.
 *
 * Usage: node tests/live-acceptance.mjs [baseUrl]
 * The demo assets are generated by engine/voice_engine.py demo.
 */
import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(HERE, '..')
const BASE = (process.argv[2] || 'http://127.0.0.1:61999').replace(/\/$/, '')
const API = `${BASE}/plugins/dsh-voice-unified/api`
const DEMO = path.join(ROOT, 'output', 'demo')
const report = []
const record = (name, ok, detail) => {
  report.push({ name, ok, detail })
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ` — ${detail}` : ''}`)
  if (!ok) process.exitCode = 2
}

async function req(method, endpoint, body) {
  const init = { method, headers: {} }
  if (body !== undefined) {
    init.headers['content-type'] = 'application/json'
    init.body = JSON.stringify(body)
  }
  const response = await fetch(API + endpoint, init)
  const data = await response.json().catch(() => null)
  if (!response.ok || data?.ok === false) {
    const error = new Error(data?.error || `HTTP ${response.status}`)
    error.code = data?.code
    error.status = response.status
    throw error
  }
  return data
}

async function uploadSample(profileId, file, index) {
  const buffer = await readFile(file)
  return req('POST', `/profiles/${profileId}/samples`, {
    filename: `sample-${index}.wav`,
    dataBase64: buffer.toString('base64'),
  })
}

async function waitTraining(profileId, timeoutMs = 180000) {
  const started = Date.now()
  while (Date.now() - started < timeoutMs) {
    const detail = await req('GET', `/profiles/${profileId}`)
    if (detail.profile.training && detail.profile.training.status !== 'training') return detail.profile
    await new Promise((resolve) => setTimeout(resolve, 500))
  }
  throw new Error('training timeout')
}

try {
  const health = await req('GET', '/health')
  record('引擎健康检查', health.ok && health.engine?.ok === true, `${health.ttsEngine} / ffmpeg=${health.ffmpeg?.installed}`)

  const suffix = Date.now().toString().slice(-6)
  const profiles = []
  for (const [index, key] of ['profile-a', 'profile-b', 'profile-c'].entries()) {
    const profile = await req('POST', '/profiles', {
      name: `验收音色${String.fromCharCode(65 + index)}-${suffix}`,
      description: `验收脚本创建：${key}`,
      tags: ['验收', `组${String.fromCharCode(65 + index)}`],
    })
    profiles.push(profile.profile)
  }
  record('创建 3 个音色档案', profiles.length === 3, profiles.map((item) => item.name).join(' / '))

  const samplesDir = (key) => path.join(DEMO, 'samples', key)
  await uploadSample(profiles[0].id, path.join(samplesDir('profile-a'), 'sample-1.wav'), 1)
  const firstTrain = await req('POST', `/profiles/${profiles[0].id}/train`, { note: 'v1 单样本' })
  record('异步训练任务创建', Boolean(firstTrain.jobId), firstTrain.jobId)
  const afterFirst = await waitTraining(profiles[0].id)
  const v1 = afterFirst.currentVersion
  record('训练 v1 完成', afterFirst.training?.status === 'done' && Boolean(v1), `v=${v1?.id} similarity=${v1?.similarity}`)
  const preview1 = await req('POST', `/profiles/${profiles[0].id}/preview`, { text: '这是第一次训练后的试听。', emotion: 'tender' })
  record('v1 试听', Boolean(preview1.audioUrl), `similarity=${preview1.similarity}`)

  for (const [index, file] of ['sample-2.wav', 'sample-3.wav'].entries()) {
    await uploadSample(profiles[0].id, path.join(samplesDir('profile-a'), file), index + 2)
  }
  await req('POST', `/profiles/${profiles[0].id}/train`, { note: 'v2 增量样本' })
  const afterSecond = await waitTraining(profiles[0].id)
  const v2 = afterSecond.currentVersion
  const preview2 = await req('POST', `/profiles/${profiles[0].id}/preview`, { text: '这是第一次训练后的试听。', emotion: 'tender' })
  record('追加样本后重新训练', afterSecond.sampleCount === 3 && v2?.id !== v1?.id, `${v1?.id} -> ${v2?.id}`)
  record('相似度可感知提升', Number(preview2.similarity) > Number(preview1.similarity), `${preview1.similarity} -> ${preview2.similarity}`)

  await req('POST', `/profiles/${profiles[0].id}/rollback`, { versionId: v1.id })
  const rolled = await req('GET', `/profiles/${profiles[0].id}`)
  record('回滚到旧版本', rolled.profile.currentVersion.id === v1.id, `${rolled.profile.currentVersion.id}`)
  await req('POST', `/profiles/${profiles[0].id}/rollback`, { versionId: v2.id })

  await req('PATCH', `/profiles/${profiles[0].id}`, { name: `验收改名-${suffix}`, description: '已重命名' })
  const renamed = await req('GET', `/profiles/${profiles[0].id}`)
  record('重命名与描述更新', renamed.profile.name.startsWith('验收改名-'), renamed.profile.name)

  for (const [index, profile] of profiles.entries()) {
    const key = ['profile-a', 'profile-b', 'profile-c'][index]
    if (index > 0) {
      for (const [sampleIndex, file] of ['sample-1.wav', 'sample-2.wav', 'sample-3.wav'].entries()) {
        await uploadSample(profile.id, path.join(samplesDir(key), file), sampleIndex + 1)
      }
      await req('POST', `/profiles/${profile.id}/train`, { note: '验收训练' })
      const trained = await waitTraining(profile.id)
      record(`训练音色 ${String.fromCharCode(66 + index)}`, trained.training?.status === 'done', `v=${trained.currentVersion?.id}`)
    }
  }

  await req('POST', `/profiles/${profiles[0].id}/default`)
  const defaulted = await req('GET', '/profiles')
  record('设置全局默认音色', defaulted.defaultProfileId === profiles[0].id, defaulted.profiles.find((p) => p.isDefault)?.name)

  const emotions = ['calm', 'happy', 'tender', 'serious', 'comforting', 'excited', 'sad']
  const texts = emotions.map((emotion) => req('POST', `/profiles/${profiles[1].id}/preview`, { text: '同一句文本，不同情感语气。', emotion }))
  const emotionResults = await Promise.all(texts)
  record('七种情感标签均生成语音', emotionResults.every((item) => item.audioUrl), emotions.join('/'))

  const off = await req('PATCH', '/settings', { autoReply: false })
  const on = await req('PATCH', '/settings', { autoReply: true })
  record('关闭并重新开启自动语音回复', off.settings.autoReply === false && on.settings.autoReply === true)

  const cache = await req('POST', '/music/bind-cache', { directory: DEMO })
  record('绑定音乐缓存目录', cache.entries.length >= 1, `${cache.entries.length} 个文件`)
  const noCache = await req('POST', '/cover/run', { songName: `不存在的歌曲-${suffix}`, deliver: false }).then(() => false).catch((error) => error.code === 'NO_CACHE_FILE' || error.code === 'CACHE_NOT_FOUND')
  record('无缓存时明确提示', noCache)

  const cover = await req('POST', '/cover/run', {
    sourcePath: path.join(DEMO, 'demo-original.wav'),
    songName: `验收翻唱-${suffix}`,
    profileId: profiles[1].id,
    deliver: false,
  })
  const jobId = cover.job.id
  let job
  for (let i = 0; i < 240; i += 1) {
    const payload = await req('GET', `/cover/jobs/${jobId}`)
    job = payload.job
    if (job.status === 'done' || job.status === 'failed') break
    await new Promise((resolve) => setTimeout(resolve, 1000))
  }
  record('翻唱任务完成', job?.status === 'done', `stage=${job?.stage} progress=${job?.progress}`)
  record('输出完整 MP3 与 WAV', Boolean(job?.output?.mp3 && job?.output?.wav), `${job?.output?.duration}s / ${job?.output?.size}B`)

  const audioUrl = job.output.mp3
  const audio = await fetch(`${BASE}${audioUrl}`, { headers: { range: 'bytes=0-1023' } })
  record('对话内音频可 Range 播放', audio.status === 206, `HTTP ${audio.status}`)
  const exported = await req('POST', `/cover/jobs/${jobId}/export`, { format: 'mp3' })
  record('手动导出 MP3', Boolean(exported.path), exported.path)

  const tempDefaultBefore = (await req('GET', '/profiles')).defaultProfileId
  const tempCover = await req('POST', '/cover/run', {
    sourcePath: path.join(DEMO, 'demo-original.wav'),
    songName: `临时音色翻唱-${suffix}`,
    profileId: profiles[2].id,
    deliver: false,
  })
  const tempDefaultAfter = (await req('GET', '/profiles')).defaultProfileId
  record('临时指定非默认音色且不改默认', tempCover.job.profileId === profiles[2].id && tempDefaultBefore === tempDefaultAfter, `${tempCover.job.profileName}`)

  const deleted = await req('DELETE', `/profiles/${profiles[2].id}`)
  const listAfterDelete = await req('GET', '/profiles')
  record('删除音色档案', !listAfterDelete.profiles.some((profile) => profile.id === profiles[2].id), deleted.ok ? 'ok' : '')

  const summary = { passed: report.filter((item) => item.ok).length, total: report.length, report }
  console.log('\nSUMMARY', JSON.stringify(summary, null, 2))
} catch (error) {
  console.error('ACCEPTANCE ERROR', error)
  process.exitCode = 1
}
